'use strict';
let calendarMode='month',calendarCursor=today(),calendarSelected=today(),restInterval;
function calendarShift(date,days){const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10)}
function calendarEntries(){return [...(data.events||[]).map(v=>({...v,kind:'event'})),...data.quests.map(v=>({id:v.id,title:v.title,date:v.date,time:'',kind:'quest'})),...data.bosses.map(v=>({id:v.id,title:v.name,date:v.date,time:'',kind:'boss'}))].sort((a,b)=>(a.date+(a.time||'')).localeCompare(b.date+(b.time||'')))}
function calendarDay(date){const items=calendarEntries().filter(v=>v.date===date);return `<button class="cal-day ${date===today()?'is-today':''} ${date===calendarSelected?'selected':''}" data-cal-day="${date}"><b>${Number(date.slice(-2))}</b>${items.slice(0,3).map(v=>`<span class="cal-dot ${v.kind}">${esc(v.title)}</span>`).join('')}${items.length>3?`<small>+${items.length-3}</small>`:''}</button>`}
calendarBody=function(){const first=calendarCursor.slice(0,7)+'-01',d=new Date(first+'T12:00:00Z'),year=d.getUTCFullYear(),month=d.getUTCMonth(),start=calendarShift(first,-d.getUTCDay());let body;if(calendarMode==='month')body=`<div class="cal-weekdays">${['日','一','二','三','四','五','六'].map(v=>`<span>${v}</span>`).join('')}</div><div class="cal-grid">${Array.from({length:42},(_,i)=>calendarDay(calendarShift(start,i))).join('')}</div>`;else if(calendarMode==='week'){const wd=new Date(calendarCursor+'T12:00:00Z').getUTCDay(),ws=calendarShift(calendarCursor,-wd);body=`<div class="cal-week-list">${Array.from({length:7},(_,i)=>{const date=calendarShift(ws,i);return `<section>${calendarDay(date)}<span>${['星期日','星期一','星期二','星期三','星期四','星期五','星期六'][i]}</span><div>${calendarRows(date)}</div></section>`}).join('')}</div>`}else body=`<div class="cal-agenda">${calendarEntries().filter(v=>v.date>=first&&v.date<new Date(Date.UTC(year,month+3,1)).toISOString().slice(0,10)).map(calendarEntryRow).join('')||'<p class="empty">未來三個月未有安排。</p>'}</div>`;return `<div class="calendar-app"><div class="cal-toolbar"><button class="ghost" data-cal-nav="-1" aria-label="上一個時段">‹</button><h3>${year} 年 ${month+1} 月</h3><button class="ghost" data-cal-nav="1" aria-label="下一個時段">›</button><button class="ghost" data-cal-today>今日</button><button class="primary small-btn" data-cal-add>＋活動</button></div><div class="cal-segments">${[['month','月'],['week','週'],['agenda','三個月日程']].map(([id,name])=>`<button data-cal-mode="${id}" class="${calendarMode===id?'active':''}" aria-pressed="${calendarMode===id}">${name}</button>`).join('')}</div>${body}<h3 class="cal-selected-heading">${esc(calendarSelected)} 的安排</h3>${calendarRows(calendarSelected)}<p class="subtle">家長同小朋友共用此家庭日曆。任務與 Boss 日期會自動顯示。</p></div>`};
function calendarEntryRow(v){return `<div class="cal-entry ${v.kind}"><span><small>${esc(v.date)} ${esc(v.time||'全日')} · ${v.kind==='quest'?'任務':v.kind==='boss'?'Boss':v.createdBy==='parent'?'家長加入':'小朋友加入'}</small><strong>${esc(v.title)}</strong>${v.note?`<p>${esc(v.note)}</p>`:''}</span>${v.kind==='event'?`<button class="ghost small-btn" data-cal-edit="${esc(v.id)}">編輯</button>`:''}</div>`}
function calendarRows(date){return calendarEntries().filter(v=>v.date===date).map(calendarEntryRow).join('')||'<p class="cal-empty">當日未有安排，留返少少時間休息。</p>'}
function openSharedCalendar(){openModal('shared-calendar',calendarBody(),'家庭冒險日曆');$('.modal').classList.add('calendar-modal')}
function calendarEditor(id){const v=(data.events||[]).find(v=>v.id===id)||{date:calendarSelected};openModal('calendar-edit',`<form id="calendar-event-form" data-id="${esc(id||'')}"><label class="field" for="event-title">活動名稱</label><input class="input" id="event-title" name="title" maxlength="80" value="${esc(v.title||'')}" required><div class="form-grid"><div><label class="field" for="event-date">日期</label><input class="input" type="date" id="event-date" name="date" value="${esc(v.date)}" required></div><div><label class="field" for="event-time">時間（留空為全日）</label><input class="input" type="time" id="event-time" name="time" value="${esc(v.time||'')}"></div></div><label class="field" for="event-note">備註</label><textarea class="input" id="event-note" name="note" maxlength="500">${esc(v.note||'')}</textarea><p class="error" id="event-error" role="alert"></p><div class="inline-actions" style="margin-top:20px"><button type="button" class="ghost" data-cal-open>返回日曆</button><button class="primary" type="submit">儲存活動</button></div></form>`,'安排一個新章節')}
const calendarDashboard=dashboardNav;dashboardNav=function(){return calendarDashboard()+`<button class="guild-nav-btn" data-cal-open>${icon('calendar')} 家庭日曆</button>`};
function parentFingerprint(){return JSON.stringify([data.quests,data.bosses,data.events,data.gifts,data.customAchievements,data.goals,data.xpPerLevel])}
let parentBaseline=parentFingerprint();const calendarPersist=persist;persist=function(){const fp=parentFingerprint();if(sessionRole==='parent'&&fp!==parentBaseline){data.parentUpdates??=[];data.parentUpdates.unshift({id:crypto.randomUUID(),at:new Date().toISOString(),text:'家長更新咗任務、日曆或成長安排，睇吓有咩新消息。'});data.parentUpdates=data.parentUpdates.slice(0,30)}parentBaseline=fp;calendarPersist()};
const calendarActivate=activateFamily;activateFamily=function(p){calendarActivate(p);parentBaseline=parentFingerprint()};
function unseenUpdates(){return (data.parentUpdates||[]).filter(v=>!(data.seenUpdates||[]).includes(v.id))}
const calendarRoom=room;room=function(){const updates=unseenUpdates();return calendarRoom().replace('<footer class="room-footer">',`<button class="hotspot h-rest" data-rest-open>${icon('moon')} 自律休息</button>${updates.length?`<button class="room-new-signal" data-updates-open>✦ 家長有新消息 <b>${updates.length}</b></button>`:''}<footer class="room-footer">`)};
function showParentUpdates(){const rows=unseenUpdates();data.seenUpdates=(data.parentUpdates||[]).map(v=>v.id);persist();$('.room-new-signal')?.remove();openModal('updates',rows.map(v=>`<div class="calendar-event"><strong>✦ ${esc(v.text)}</strong><p>${esc(new Date(v.at).toLocaleString('zh-HK',{timeZone:'Asia/Hong_Kong'}))}</p></div>`).join('')+`<div class="inline-actions"><button class="primary" data-cal-open>打開家庭日曆</button><button class="ghost" data-action="quests">睇任務板</button></div>`,'公會長的新消息')}
function openRest(){if(timer){notify('請先儲存專注任務，再開始休息。');return}if(data.restEndsAt>Date.now()){drawRest();return}openModal('rest-setup',`<div class="rest-intro">${icon('moon')}<h3>休息一下，等精神回來。</h3><p class="subtle">可以自由活動、飲水或者伸展。時間到會提醒你返嚟。</p></div><form id="rest-form"><label class="field" for="rest-minutes">休息幾多分鐘？</label><input class="input" type="number" min="1" max="60" value="5" id="rest-minutes" name="minutes" required><button class="primary" style="margin-top:20px" type="submit">開始自律休息</button></form>`,'自律休息')}
function drawRest(){openModal('rest-timer',`<div class="rest-bedroom"><div class="rest-sleeper" style="background-position:${data.hero%3*50}% ${Math.floor(data.hero/3)*100}%"></div><span class="rest-zzz">z Z</span><div class="rest-caption">勇者休息中</div></div><div class="timer-number rest-clock" id="rest-clock"></div><p class="subtle" id="rest-note">去飲啖水、郁下身，等精神回來。</p><div class="inline-actions" style="margin-top:20px"><button class="ghost" data-rest-close>收起計時</button><button class="primary" data-rest-end>休息夠，返去做任務</button></div>`,'自律休息');tickRest()}
function tickRest(){if(!data.restEndsAt)return;const remaining=Math.max(0,Math.ceil((data.restEndsAt-Date.now())/1000));if($('#rest-clock'))$('#rest-clock').textContent=formatTime(remaining);if(remaining===0){data.restEndsAt=null;data.restReminder=true;persist();playEffect('finish');notify('休息時間到喇！返嚟揀下一個任務啦。');if(modal==='rest-timer'){$('#rest-note').textContent='休息完成，係時候繼續你嘅冒險喇！';$('.rest-caption').textContent='精神回來，再出發！'}else if(page==='room'&&!modal)openRestReminder()}}
function openRestReminder(){data.restReminder=false;persist();openModal('rest-done','<h3>休息完成，歡迎返嚟！</h3><p class="subtle" style="margin:18px 0">準備好文具，揀下一個小目標繼續努力。</p><button class="primary" data-action="quests">繼續做任務</button>','再出發')}
restInterval=setInterval(tickRest,1000);
const restRender=render;render=function(){restRender();if(page==='room'&&data.restReminder&&!modal)openRestReminder()};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.action==='calendar'){e.preventDefault();e.stopImmediatePropagation();openSharedCalendar();return}if(b.hasAttribute('data-cal-open')){openSharedCalendar();return}if(b.dataset.calMode){calendarMode=b.dataset.calMode;openSharedCalendar();return}if(b.dataset.calNav){if(calendarMode==='week')calendarCursor=calendarShift(calendarCursor,Number(b.dataset.calNav)*7);else{const d=new Date(calendarCursor.slice(0,7)+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+Number(b.dataset.calNav));calendarCursor=d.toISOString().slice(0,10)}openSharedCalendar();return}if(b.hasAttribute('data-cal-today')){calendarCursor=calendarSelected=today();openSharedCalendar();return}if(b.dataset.calDay){calendarSelected=b.dataset.calDay;openSharedCalendar();return}if(b.hasAttribute('data-cal-add')){calendarEditor();return}if(b.dataset.calEdit){calendarEditor(b.dataset.calEdit);return}if(b.hasAttribute('data-updates-open'))showParentUpdates();if(b.hasAttribute('data-rest-open'))openRest();if(b.hasAttribute('data-rest-close'))closeModal();if(b.hasAttribute('data-rest-end')){data.restEndsAt=null;data.restReminder=false;persist();closeModal();show('quests')}},true);
document.addEventListener('submit',e=>{if(!['calendar-event-form','rest-form'].includes(e.target.id))return;e.preventDefault();e.stopImmediatePropagation();const f=new FormData(e.target);if(e.target.id==='rest-form'){const mins=Number(f.get('minutes'));if(!Number.isInteger(mins)||mins<1||mins>60)return;data.restEndsAt=Date.now()+mins*60000;data.restReminder=false;persist();drawRest();return}const title=String(f.get('title')).trim(),date=String(f.get('date'));if(!title||!/^\d{4}-\d{2}-\d{2}$/.test(date)){$('#event-error').textContent='請填好活動名稱同日期。';return}data.events??=[];const old=data.events.find(v=>v.id===e.target.dataset.id);const value={title,date,time:String(f.get('time')||''),note:String(f.get('note')||'').trim(),updatedBy:sessionRole,updatedAt:new Date().toISOString()};if(old)Object.assign(old,value);else data.events.push({...value,id:crypto.randomUUID(),createdBy:sessionRole});calendarCursor=calendarSelected=date;persist();openSharedCalendar();notify('家庭日曆已更新。')},true);
render();
